const pago = $input.first().json.body.pago;
const afiliado = $input.first().json.body.afiliado;

const nombre = afiliado.nombre || 'Afiliado';
const correo = afiliado.correo || '';
const telefono = afiliado.telefono || '';
const valor = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP' }).format(pago.valor_pagado);
const fecha = pago.fecha_pago;
const factura = `FAC-${new Date().getFullYear()}-${String(pago.id_pago).padStart(4, '0')}`;

// Formato para WhatsApp (Twilio)
const mensajeWhatsApp = `🏋️ *MetaFit — Factura de Membresía*\n\nHola ${nombre},\n\nTu pago ha sido registrado:\n\n📋 Factura: *${factura}*\n💰 Valor: *${valor}*\n📅 Fecha: ${fecha}\n💳 Método: ${pago.metodo_pago}\n📆 Vence: ${pago.fecha_vencimiento}\n\nGracias por tu confianza. 💪\n_ Sport Gym Sede 80_`;

// Formato para correo Brevo
const asunto = `MetaFit — Tu factura ${factura} está lista`;
const htmlCorreo = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;">
  <div style="background:#e31c25;color:#fff;padding:20px;border-radius:8px 8px 0 0;text-align:center;">
    <h1 style="margin:0;">🏋️ MetaFit</h1>
    <p style="margin:5px 0 0;">Factura de Membresía</p>
  </div>
  <div style="background:#f8f9fa;padding:20px;border:1px solid #dee2e6;">
    <p>Hola <strong>${nombre}</strong>,</p>
    <p>Tu pago ha sido registrado exitosamente:</p>
    <table style="width:100%;border-collapse:collapse;">
      <tr><td style="padding:8px;border-bottom:1px solid #dee2e6;"><strong>Factura:</strong></td><td>${factura}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #dee2e6;"><strong>Valor:</strong></td><td>${valor}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #dee2e6;"><strong>Fecha:</strong></td><td>${fecha}</td></tr>
      <tr><td style="padding:8px;border-bottom:1px solid #dee2e6;"><strong>Método:</strong></td><td>${pago.metodo_pago}</td></tr>
      <tr><td style="padding:8px;"><strong>Vence:</strong></td><td>${pago.fecha_vencimiento}</td></tr>
    </table>
    <p style="margin-top:20px;color:#666;">Gracias por tu confianza. 💪</p>
  </div>
  <div style="text-align:center;padding:10px;color:#999;font-size:12px;">
    Sport Gym Sede 80 — Bogotá, Colombia
  </div>
</div>`;

return [{
  json: {
    nombre, correo, telefono,
    mensajeWhatsApp,
    asunto, htmlCorreo,
    factura, valor, fecha,
    id_pago: pago.id_pago
  }
}];
